/** Sizing rules for profile pictures. Free of Android types so they can be unit tested. */
object ProfileImagePolicy {

    /** Profile pictures are stored as a square of this many pixels per side. */
    const val SIZE_PX = 256

    /**
     * Largest stored JPEG, in bytes, before Base64 encoding. Profiles are loaded
     * often (the admin profile list loads every one), so pictures stay small.
     */
    const val MAX_BYTES = 60_000

    /** JPEG qualities tried in order until the picture fits in [MAX_BYTES]. */
    val QUALITIES = listOf(85, 70, 55, 40)

    /**
     * The largest power-of-two downsampling factor that still leaves the shorter
     * side of a [width] x [height] image at least [target] pixels, so the photo
     * isn't decoded at full resolution.
     */
    fun sampleSizeFor(width: Int, height: Int, target: Int = SIZE_PX): Int {
        val shorter = minOf(width, height)
        if (shorter <= 0) return 1
        var sample = 1
        while (shorter / (sample * 2) >= target) sample *= 2
        return sample
    }

    /** The centred square to crop from a [width] x [height] image, as (left, top, side). */
    fun centerSquare(width: Int, height: Int): Triple<Int, Int, Int> {
        val side = minOf(width, height)
        return Triple((width - side) / 2, (height - side) / 2, side)
    }

    /** Degrees to rotate a photo clockwise for its EXIF [orientation] so it shows upright. */
    fun rotationFor(orientation: Int): Float = when (orientation) {
        ExifInterface.ORIENTATION_ROTATE_90 -> 90f
        ExifInterface.ORIENTATION_ROTATE_180 -> 180f
        ExifInterface.ORIENTATION_ROTATE_270 -> 270f
        else -> 0f
    }

    /** The Base64 payload of [stored], without any `data:image/...;base64,` prefix. */
    fun base64Payload(stored: String): String = stored.substringAfter("base64,", stored).trim()
}

/**
 * Loads the photo at [uri], turns it upright, crops it to a centred square, scales
 * it to [ProfileImagePolicy.SIZE_PX] and returns it as a Base64 JPEG no larger than
 * [ProfileImagePolicy.MAX_BYTES].
 *
 * @return the encoded picture, or null if the photo couldn't be read or made small enough.
 */
suspend fun encodeProfileImage(context: Context, uri: Uri): String? = withContext(Dispatchers.IO) {
    runCatching {
        val resolver = context.contentResolver
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        resolver.openInputStream(uri)?.use { BitmapFactory.decodeStream(it, null, bounds) }
        if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return@runCatching null

        val options = BitmapFactory.Options().apply {
            inSampleSize = ProfileImagePolicy.sampleSizeFor(bounds.outWidth, bounds.outHeight)
        }
        val decoded = resolver.openInputStream(uri)?.use { BitmapFactory.decodeStream(it, null, options) }
            ?: return@runCatching null
        val orientation = resolver.openInputStream(uri)?.use {
            ExifInterface(it).getAttributeInt(ExifInterface.TAG_ORIENTATION, ExifInterface.ORIENTATION_NORMAL)
        } ?: ExifInterface.ORIENTATION_NORMAL

        val (left, top, side) = ProfileImagePolicy.centerSquare(decoded.width, decoded.height)
        val scale = ProfileImagePolicy.SIZE_PX.toFloat() / side
        val matrix = Matrix().apply {
            postScale(scale, scale)
            postRotate(ProfileImagePolicy.rotationFor(orientation))
        }
        val square = Bitmap.createBitmap(decoded, left, top, side, side, matrix, true)

        val out = ByteArrayOutputStream()
        for (quality in ProfileImagePolicy.QUALITIES) {
            out.reset()
            square.compress(Bitmap.CompressFormat.JPEG, quality, out)
            if (out.size() <= ProfileImagePolicy.MAX_BYTES) break
        }
        if (square !== decoded) square.recycle()
        decoded.recycle()

        if (out.size() > ProfileImagePolicy.MAX_BYTES) null
        else Base64.encodeToString(out.toByteArray(), Base64.NO_WRAP)
    }.getOrNull()
}

/** Decodes a stored profile picture, or returns null if [stored] is blank or not an image. */
fun decodeProfileImage(stored: String?): ImageBitmap? {
    if (stored.isNullOrBlank()) return null
    return runCatching {
        val bytes = Base64.decode(ProfileImagePolicy.base64Payload(stored), Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)?.asImageBitmap()
    }.getOrNull()
}

/**
 * A round profile picture. Shows [image] if it decodes, otherwise the first letter
 * of [name] (or a "?" when there's no name) on a plain circle.
 */
@Composable
fun ProfileAvatar(image: String?, name: String, size: Dp = 96.dp, modifier: Modifier = Modifier) {
    val bitmap = remember(image) { decodeProfileImage(image) }
    if (bitmap != null) {
        Image(
            bitmap = bitmap,
            contentDescription = "Profile picture",
            contentScale = ContentScale.Crop,
            modifier = modifier.size(size).clip(CircleShape).testTag("profileImage"),
        )
    } else {
        Box(
            modifier = modifier
                .size(size)
                .clip(CircleShape)
                .background(Color(0xFF283618))
                .testTag("profileImagePlaceholder"),
            contentAlignment = Alignment.Center,
        ) {
            Text(
                name.trim().firstOrNull()?.uppercase() ?: "?",
                color = Color.White,
                fontSize = (size.value * 0.4f).sp,
            )
        }
    }
}

/**
 * Picks a photo for a profile picture. [choose] calls [onPicked] once a photo is
 * chosen and is being processed, then [onResult] with the encoded picture, or null
 * if it couldn't be used. If the user backs out of the picker, neither is called.
 */
fun interface ProfileImageChooser {
    fun choose(onPicked: () -> Unit, onResult: (String?) -> Unit)
}

/** A [ProfileImageChooser] that opens the system photo picker and encodes the photo with [encodeProfileImage]. */
@Composable
fun rememberProfileImageChooser(): ProfileImageChooser {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    // Callbacks for the picker that's currently open.
    val pending = remember { mutableStateOf<Pair<() -> Unit, (String?) -> Unit>?>(null) }
    val launcher = rememberLauncherForActivityResult(ActivityResultContracts.PickVisualMedia()) { uri ->
        val callbacks = pending.value
        pending.value = null
        if (uri == null || callbacks == null) return@rememberLauncherForActivityResult
        val (onPicked, onResult) = callbacks
        onPicked()
        scope.launch { onResult(encodeProfileImage(context, uri)) }
    }
    return remember(launcher) {
        ProfileImageChooser { onPicked, onResult ->
            pending.value = onPicked to onResult
            launcher.launch(PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly))
        }
    }
}
